import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FiUser, FiPhone, FiUserCheck } from 'react-icons/fi';

const Register = () => {
    const [name, setName] = useState('');
    const [phone, setPhone] = useState('');
    const [userType, setUserType] = useState('comprador');
    const [loading, setLoading] = useState(false);
    const { register } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        const result = await register(name, phone, userType);
        if (result.success) {
            if (userType === 'vendedor') {
                navigate('/seller/dashboard');
            } else {
                navigate('/');
            }
        }
        setLoading(false);
    };

    return (
        <div className="max-w-md mx-auto">
            <div className="bg-white rounded-xl shadow-md p-8">
                <h2 className="text-2xl font-bold text-center mb-6">Criar nova conta</h2>
                
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Nome completo</label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center">
                                <FiUser className="text-gray-400" />
                            </div>
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                placeholder="Seu nome"
                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600 focus:ring-1 focus:ring-primary-600"
                                required
                            />
                        </div>
                    </div>

                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Número de Telefone</label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center">
                                <FiPhone className="text-gray-400" />
                            </div>
                            <input
                                type="tel"
                                value={phone}
                                onChange={(e) => setPhone(e.target.value)}
                                placeholder="923 456 789"
                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600 focus:ring-1 focus:ring-primary-600"
                                required
                            />
                        </div>
                        <p className="text-xs text-gray-500 mt-1">Digite apenas os números, sem espaços</p>
                    </div>

                    <div className="mb-6">
                        <label className="block text-gray-700 mb-2">Tipo de conta</label>
                        <div className="grid grid-cols-2 gap-4">
                            <button
                                type="button"
                                onClick={() => setUserType('comprador')}
                                className={`py-2 px-4 rounded-lg border transition ${
                                    userType === 'comprador' 
                                        ? 'bg-primary-600 text-white border-primary-600' 
                                        : 'border-gray-300 text-gray-700 hover:border-primary-600'
                                }`}
                            >
                                <FiUserCheck className="inline mr-2" />
                                Comprador
                            </button>
                            <button
                                type="button"
                                onClick={() => setUserType('vendedor')}
                                className={`py-2 px-4 rounded-lg border transition ${
                                    userType === 'vendedor' 
                                        ? 'bg-primary-600 text-white border-primary-600' 
                                        : 'border-gray-300 text-gray-700 hover:border-primary-600'
                                }`}
                            >
                                <FiUser className="inline mr-2" />
                                Vendedor
                            </button>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-primary-600 text-white py-2 rounded-lg hover:bg-primary-700 transition disabled:opacity-50"
                    >
                        {loading ? 'Cadastrando...' : 'Cadastrar'}
                    </button>
                </form>

                <p className="text-center text-gray-600 mt-4">
                    Já tem conta?{' '}
                    <Link to="/login" className="text-primary-600 hover:underline">
                        Faça login
                    </Link>
                </p>
            </div>
        </div>
    );
};

export default Register;
